// Verify X-Pressline-Signature (same scheme as lib/n8n/sign.ts). Throws on bad/stale.
const crypto = require('crypto');
const S = $('Secrets').first().json;
let secret; try { secret = $env.N8N_WEBHOOK_SECRET; } catch (e) { /* $env disabled */ }
if (!secret) secret = S.secret;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET missing: set it in n8n env or in the Secrets node');
const hook = $('Webhook').first();
const headers = hook.json.headers || {};
const header = headers['x-pressline-signature'] || headers['X-Pressline-Signature'];
if (!header) throw new Error('unsigned request: missing x-pressline-signature');
// Raw body: Webhook node has "Raw Body" on, so the exact bytes are in binary.data.
let raw = null;
if (hook.binary && hook.binary.data) {
  try { raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'); } catch (e) { /* helper unavailable */ }
  if (raw === null) {
    const d = hook.binary.data.data || '';
    if (/^[A-Za-z0-9+/]+=*$/.test(d)) raw = Buffer.from(d, 'base64').toString('utf8');
  }
}
if (raw === null) raw = JSON.stringify(hook.json.body ?? {}); // last resort: app sends compact JSON.stringify
const parts = Object.fromEntries(String(header).split(',').map((kv) => kv.split('=')));
const t = Number(parts.t); const v1 = parts.v1 || '';
const now = Math.floor(Date.now() / 1000);
if (!Number.isFinite(t) || Math.abs(now - t) > 300) throw new Error('stale signature (older than 5 minutes)');
const expected = crypto.createHmac('sha256', secret).update(`${t}.${raw}`).digest('hex');
const a = Buffer.from(expected, 'hex'); const b = Buffer.from(v1, 'hex');
if (a.length === 0 || a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('bad signature');
let payload; try { payload = JSON.parse(raw); } catch (e) { payload = hook.json.body ?? {}; }
return [{ json: payload }];

// Sign outbound calls to the app: X-Pressline-Signature: t=<unix>,v1=<hmac sha256 hex of "<t>.<rawBody>">
const crypto = require('crypto');
const S = $('Secrets').first().json;
let secret; try { secret = $env.N8N_WEBHOOK_SECRET; } catch (e) { /* $env disabled */ }
if (!secret) secret = S.secret;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET missing: set it in n8n env or in the Secrets node');
const appUrl = String(S.appUrl || 'https://pressline.up.railway.app').replace(/\/+$/, '');
const n8nUrl = String(S.n8nUrl || 'https://deathcorps187.app.n8n.cloud').replace(/\/+$/, '');
const items = $input.all();
const calls = [];
const p = $('Verify').first().json;
calls.push({ method: 'GET', path: `/api/orders/${encodeURIComponent(p.order_id)}` });
return calls.filter(Boolean).map((c) => {
  const method = String(c.method || 'POST').toUpperCase();
  const raw = method === 'GET' ? '' : JSON.stringify(c.body ?? {});
  const t = Math.floor(Date.now() / 1000);
  const mac = crypto.createHmac('sha256', secret).update(`${t}.${raw}`).digest('hex');
  const url = c.url || (appUrl + c.path);
  return { json: { url, method, raw, signature: `t=${t},v1=${mac}`, meta: c.meta || {} } };
});

